from format_lecon import Lesson,paras,table,steps
from diagnostics import comparison
from medicaments import paracetamol
l=Lesson('Otalgie')
l.add('L’otalgie est une douleur ressentie dans l’oreille. Les {deux grandes origines} sont une atteinte de l’oreille elle-même et une douleur projetée depuis un autre territoire. Une otoscopie normale impose de poursuivre l’examen.',paras('L’otalgie primaire peut provenir du pavillon, du conduit, du tympan ou de l’oreille moyenne. L’otalgie référée peut provenir notamment des dents, de l’appareil manducateur ou de l’oropharynx.', 'Ne pas confondre douleur, sensation d’oreille pleine et baisse auditive. Leur association oriente le diagnostic, mais une surdité brusque doit être évaluée comme telle même si le patient parle d’oreille bouchée.'),(1,2,5,7,8,23))
l.add('Otites, obstruction du conduit et douleurs projetées sont des causes importantes en pratique. Les {contextes de survenue} orientent sans remplacer l’examen. La sélection des dix diagnostics est pédagogique et non un classement chiffré de fréquence suisse.',paras('L’enfant présente souvent une cause otologique ; objets introduits et infection respiratoire doivent être recherchés. Chez l’adulte avec oreille normale, dents et articulation temporo-mandibulaire méritent un examen attentif.', 'Baignade et manipulation favorisent une otite externe ; changement de pression et difficulté d’équilibrage orientent vers un barotraumatisme. Une douleur persistante, un terrain immunodéprimé ou des signes pharyngés changent la priorité du bilan.'),(1,2,5,7,9,14,23))
anatomie=l.subwindow('anatomie','Oreille, trompe auditive et douleur projetée',paras('Le conduit externe se termine sur le tympan ; l’oreille moyenne contient les osselets et communique avec le nasopharynx par la trompe auditive. Celle-ci participe à l’équilibrage des pressions.', 'La proximité et les connexions nerveuses sensitives entre oreille, mâchoire, dents et pharynx expliquent des douleurs projetées. Le siège ressenti ne prouve donc pas le siège de la lésion.', 'Une douleur avec baisse auditive peut relever d’une obstruction ou d’une atteinte de transmission ; une atteinte cochléaire ou neurologique doit aussi être recherchée. Les tests au diapason orientent sans remplacer une audiométrie lorsque celle-ci est nécessaire.'),(3,5,7,8,14,23))
l.add('La {localisation anatomique} guide l’examen et le traitement. Une douleur au tragus oriente vers le conduit alors qu’un tympan bombé évoque une atteinte moyenne. Un tympan normal n’exclut pas une maladie importante située ailleurs.',paras(anatomie)+paras('Les gouttes agissent dans le conduit et ne constituent pas un traitement universel de l’otalgie. L’intégrité tympanique conditionne leur sécurité ; un tympan non vu ne peut pas être déclaré intact.'),(1,2,3,16,21))
l.add('Le {tri des urgences} précède le traitement symptomatique. Certaines situations menacent audition, voies aériennes ou état neurologique. Il ne faut pas attendre le délai habituel de suivi devant un signe d’alarme.',table(['Priorité','🚩 Présentation','Action'],[['E1 — Neurologique ou infectieuse.','Déficit neurologique, sepsis, raideur méningée, tuméfaction rétroauriculaire ou pavillon décollé.','Évaluation hospitalière immédiate selon gravité ; rechercher AVC, complication otologique ou mastoïdite.'],['E2 — Audition et face.','Surdité brusque inexpliquée par conduit ou oreille moyenne ; paralysie faciale, vertige marqué.','Avis urgent, dans les 24 heures pour la surdité soudaine récente selon NICE ; filière AVC si contexte neurologique.'],['E3 — Corps étranger.','Pile bouton connue ou possible.','Retrait immédiat par équipe équipée ; pas d’irrigation.'],['E4 — Infection invasive.','Douleur profonde nocturne, granulations, diabète ou immunodépression, nerf crânien atteint.','Rechercher otite externe nécrosante ; avis ORL urgent.'],['E5 — Origine extra-auriculaire.','Gonflement du plancher, dysphagie ou gêne respiratoire ; céphalée temporale avec claudication de mâchoire ou trouble visuel.','Évaluer en urgence infection profonde ou artérite à cellules géantes ; atteinte visuelle le jour même.'],['Bilan accéléré.','Otalgie unilatérale persistante, oreille normale, masse cervicale, odynophagie ou amaigrissement.','Bilan de douleur projetée, notamment cancer ORL.']]),(1,4,7,8,9,10,12,13))
l.add('L’entretien précise début, durée, côté et facteurs déclenchants. Les {questions discriminantes} associent symptômes otologiques et recherche d’une origine projetée. Les médicaments et gestes déjà tentés doivent être identifiés.',table(['Question','Orientation'],[['Écoulement, prurit, baisse auditive, acouphènes ou vertige ?','Conduit, oreille moyenne ou atteinte interne à préciser.'],['Baignade, grattage, coton-tige, objet ou pile accessible ?','Otite externe, traumatisme ou corps étranger.'],['Vol, plongée, douleur pendant descente ou remontée ?','Barotraumatisme ou accident de plongée à caractériser.'],['Mastication, serrement des dents, douleur dentaire ?','Appareil manducateur ou foyer dentaire.'],['Déglutition, voix, masse cervicale, tabac, alcool ?','Cause pharyngée et risque tumoral.'],['Diabète, immunodépression, radiothérapie, chirurgie ou drain ?','Complications et limites des gestes locaux.'],['Vésicules, faiblesse du visage, œil qui ferme mal ?','Zona otique et risque cornéen.']]),(1,4,5,7,9,10,12,14,15))
l.add('L’examen comprend pavillon, tragus, mastoïde, conduit et tympan. Les {compléments indispensables} recherchent audition, nerfs crâniens et cause extra-auriculaire. L’examen doit rester prudent et adapté à la coopération.',paras('Décrire inflammation du conduit, cérumen, corps étranger, granulations, vésicules et état du tympan. Un tympan simplement rouge ne prouve pas une otite moyenne aiguë ; rechercher bombement et épanchement avec symptômes aigus.', 'Examiner visage, fermeture palpébrale et signes vestibulaires ou neurologiques selon la plainte. Évaluer l’audition, puis demander une audiométrie lorsque nécessaire sans retarder l’orientation d’une surdité brusque. Chez l’adulte, NICE demande un avis dans les 24 heures pour une perte inexpliquée par une cause externe ou moyenne, installée en trois jours ou moins et survenue dans les trente derniers jours.', 'Si l’oreille paraît normale, examiner dents, gencives, articulation et muscles masticateurs, bouche, pharynx et cou. Rechercher une douleur reproductible et des ganglions ; l’examen endoscopique spécialisé peut être nécessaire.'),(1,2,3,4,5,7,8,12))
l.add('Le {tableau comparatif} rapproche dix diagnostics de leurs signes utiles. Des causes peuvent coexister, par exemple cérumen et infection. L’urgence clinique prime sur l’ordre des lignes.',comparison(),(1,2,4,5,7,9,10,12,14,15))
l.add('Le diagnostic dépend de la concordance entre histoire et examen. Les {critères d’orientation} évitent une prescription fondée uniquement sur le mot otalgie. Une douleur persistante nécessite de vérifier l’hypothèse initiale.',paras('Douleur au tragus avec conduit inflammatoire soutient l’otite externe ; bombement tympanique et épanchement dans un tableau aigu soutiennent l’otite moyenne. Un épanchement sans inflammation aiguë relève d’une autre situation.', 'Un bouchon peut être responsable d’une gêne ou empêcher le diagnostic. Après extraction, il faut revoir tympan et symptômes ; la présence de cire ne permet pas d’écarter une autre maladie.', 'Une douleur reproduite par mastication ou examen dentaire soutient une origine projetée. Une otalgie unilatérale persistante avec oreille normale reste à explorer même en l’absence de facteur de risque tumoral connu.'),(1,2,5,7,8,12,24))
l.add('Les examens complémentaires répondent à une question clinique. Le {bilan dirigé} évite une imagerie systématique d’une otalgie simple. L’orientation urgente peut précéder la confirmation complète.',table(['Situation','Examens utiles'],[['Otite externe ou moyenne simple.','Examen clinique et otoscopie ; microbiologie selon préparation, échec ou terrain.'],['Baisse auditive ou doute de transmission.','Audiométrie, tympanométrie selon indication.'],['Otite nécrosante suspectée.','Bilan biologique, prélèvements et imagerie osseuse/tissus mous ; biopsie si malignité suspectée.'],['Douleur projetée ou masse.','Examen dentaire ou ORL ciblé, endoscopie, imagerie et biopsie selon suspicion.'],['Après plongée avec vertige ou surdité.','Évaluation urgente ORL et médecine de plongée, profil de plongée et bilan auditif/neurologique.'],['Suspicion d’artérite à cellules géantes.','Bilan urgent spécialisé, sans retarder le traitement si suspicion forte ou atteinte visuelle.']]),(1,2,7,8,10,12,13,15))
l.add('L’{algorithme pratique} part des urgences puis de la localisation. Il aboutit à un traitement causal et à un contrôle défini. L’amélioration de la douleur ne dispense pas de surveiller une lésion persistante.',steps('Rechercher pile, surdité brusque, déficit neurologique, infection invasive, mastoïdite et urgence extra-auriculaire.', 'Examiner conduit et tympan ; si visibilité insuffisante, organiser nettoyage ou avis adapté au risque.', 'Si cause otologique identifiable, choisir le traitement compatible avec tympan, âge et terrain.', 'Si oreille normale, examiner dents, articulation, pharynx et cou ; adresser une présentation persistante ou suspecte.', 'Réévaluer une otite externe non améliorée à 48–72 heures et une otite moyenne selon âge et stratégie suisse ; revenir immédiatement si aggravation.'),(1,2,7,8,9,10,12,13,21))
antalgie=paracetamol(l)
l.add('Le soulagement de la douleur accompagne le diagnostic et son traitement. Les {principes thérapeutiques suisses} évitent antibiotiques ou gouttes systématiques. La préparation exacte détermine dose et contre-indications.',paras(antalgie)+paras('L’otite externe simple relève souvent d’un traitement local ; l’otite moyenne exige une décision antibiotique distincte selon âge, gravité et suivi. Ciproxin HC ne convient pas à une perforation connue ou supposée et n’est pas indiqué pour une otite moyenne.', 'Un corps étranger ou un bouchon nécessite une extraction adaptée, pas des manipulations répétées. Une infection nécrosante, un zona avec paralysie faciale ou une atteinte interne demande une filière spécialisée.', 'Une douleur dentaire nécessite le contrôle du foyer ; un trouble temporo-mandibulaire relève souvent d’une prise en charge conservatrice. Une tumeur ne doit pas être masquée par la répétition de traitements empiriques.'),(1,2,4,5,7,9,10,12,16,20))
l.add('La {prévention et le suivi} dépendent de la cause. Les consignes doivent être compréhensibles et compatibles avec l’état du tympan. Une évolution inhabituelle impose une nouvelle évaluation.',paras('Éviter coton-tige, grattage et introduction d’objets ; protéger des piles bouton. Entretenir les appareils auditifs et suivre les conseils de protection de l’eau en cas d’infection ou de tympan ouvert.', 'En plongée, interrompre l’activité lorsque l’équilibrage devient difficile et éviter les manœuvres forcées. Ne pas reprendre après un traumatisme auditif sans avis adapté.', 'Maintenir soins dentaires et suivi des troubles masticateurs ; signaler masse, gêne à la déglutition, baisse auditive ou douleur persistante. Expliquer quand reconsulter et comment joindre les soins urgents.'),(1,5,7,8,9,12,15,21))
l.add('Otalgie ne signifie pas automatiquement otite. Le tympan doit être évalué avant le choix de gouttes. Une oreille normale conduit à examiner bouche, mâchoire, pharynx et cou. Surdité brusque, pile et signes invasifs changent immédiatement la priorité.',refs=(1,2,4,5,7,8,9,10,12))
l.quiz([('Une otalgie prouve-t-elle une otite ?','Non : une douleur projetée est possible.'),('Une otoscopie normale termine-t-elle le bilan ?','Non : examiner notamment dents, articulation, pharynx et cou.'),('Un tympan rouge seul suffit-il au diagnostic d’otite moyenne aiguë ?','Non : rechercher tableau aigu, épanchement et bombement.'),('Que suggère une douleur au tragus avec conduit inflammatoire ?','Une otite externe.'),('Un tympan masqué peut-il être déclaré intact ?','Non.'),('Ciproxin HC convient-il à toute douleur d’oreille ?','Non : indication externe bactérienne précise, avec contre-indication si perforation connue ou supposée.'),('Une pile bouton peut-elle attendre l’échec de gouttes ?','Non : retrait immédiat, sans irrigation.'),('Une oreille soudainement bouchée peut-elle cacher une urgence ?','Oui : une surdité brusque doit être recherchée.'),('Quel tableau évoque Ramsay-Hunt ?','Otalgie, vésicules et paralysie faciale périphérique, parfois décalées dans le temps.'),('Pourquoi vérifier l’œil en cas de paralysie faciale ?','La fermeture incomplète expose la cornée.'),('Une douleur nocturne disproportionnée chez un diabétique est-elle banale ?','Non : rechercher une otite externe nécrosante.'),('Que rechercher devant une douleur à la mastication avec oreille normale ?','Cause dentaire ou temporo-mandibulaire, sans négliger les autres signes d’alarme.'),('Une otalgie persistante avec odynophagie et ganglion impose quoi ?','Un bilan ORL rapide, notamment tumoral.'),('Peut-on cumuler plusieurs médicaments contenant du paracétamol ?','Il faut compter leur dose totale ; le cumul peut provoquer un surdosage grave.')],(1,2,4,5,7,8,9,10,12,16,20))
l.write()
